module logic;
use model {Summary,Job};
use util {reverse};
record Membership {items:List<I64>,target:I64,found:Bool}
record DependencyScan {items:List<I64>,completed:List<I64>,ready:Bool}
record Candidate {found:Bool,job:Job}
record CandidateScan {items:List<Job>,completed:List<I64>,remaining:I64,best:Candidate}
record RunState {completed:List<I64>,order:List<I64>,spent:I64,remaining:I64,done:Bool}

fn contains(ids:List<I64>,target:I64)->Bool {
 let final=fold(i in List::length(ids),state:Membership=Membership {items:ids,target:target,found:false}) {
  Membership {items:List::tail(state.items),target:state.target,found:state.found || List::head(state.items)==state.target}
 };
 final.found
}

fn depsReady(deps:List<I64>,completed:List<I64>)->Bool {
 let final=fold(i in List::length(deps),state:DependencyScan=DependencyScan {items:deps,completed:completed,ready:true}) {
  DependencyScan {items:List::tail(state.items),completed:state.completed,ready:state.ready && contains(state.completed,List::head(state.items))}
 };
 final.ready
}

fn eligible(job:Job,completed:List<I64>,remaining:I64)->Bool {
 (!contains(completed,job.id) && job.cost<=remaining) && depsReady(job.deps,completed)
}

fn choose(jobs:List<Job>,completed:List<I64>,remaining:I64)->Candidate {
 let final=fold(i in List::length(jobs),state:CandidateScan=CandidateScan {items:jobs,completed:completed,remaining:remaining,best:Candidate {found:false,job:Job {id:0,cost:0,deps:List::empty<I64>()}}}) {
  let current=List::head(state.items);
  let usable=eligible(current,state.completed,state.remaining);
  let better=usable && (!state.best.found || current.id<state.best.job.id);
  CandidateScan {items:List::tail(state.items),completed:state.completed,remaining:state.remaining,best:if better {Candidate {found:true,job:current}} else {state.best}}
 };
 final.best
}

fn run(jobs:List<Job>,budget:I64)->Summary {
 let initial=RunState {completed:List::empty<I64>(),order:List::empty<I64>(),spent:0,remaining:budget,done:false};
 let final=while(state:RunState=initial; !state.done && List::length(state.completed)<List::length(jobs)) {
  let candidate=choose(jobs,state.completed,state.remaining);
  if candidate.found {
   RunState {completed:List::prepend(candidate.job.id,state.completed),order:List::prepend(candidate.job.id,state.order),spent:state.spent+candidate.job.cost,remaining:state.remaining-candidate.job.cost,done:false}
  } else {
   RunState {completed:state.completed,order:state.order,spent:state.spent,remaining:state.remaining,done:true}
  }
 };
 Summary {order:reverse(final.order),spent:final.spent,blocked:List::length(jobs)-List::length(final.completed)}
}

